Here are simple HTTP method examples in **Node.js**:

### 1. GET Request
```javascript
const http = require('http');

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/plain' });
  res.end('Hello, world! This is a GET request.');
});

// Start the server
server.listen(8000, 'localhost', () => {
  console.log('Server running on port 8000');
});
```

### 2. PUT Request
```javascript
const http = require('http');

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ message: 'PUT request received' }));
});

// Start the server
server.listen(8001, 'localhost', () => {
  console.log('Server running on port 8001');
});
```

### 3. DELETE Request
```javascript
const http = require('http');

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/plain' });
  res.end('DELETE request successfully sent.');
});

// Start the server
server.listen(8002, 'localhost', () => {
  console.log('Server running on port 8002');
});
```

### 4. PATCH Request
```javascript
const http = require('http');

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ message: 'PATCH request received' }));
});

// Start the server
server.listen(8003, 'localhost', () => {
  console.log('Server running on port 8003');
});
```

### Key Features:
- All examples handle HTTP methods in **Node.js**.
- The code is self-contained and runs on its own.
- Each request is handled with proper context (e.g., `req`, `res`).

